/** Actual mixed products must requalify every supplied cut on the same next input. */
public final class ContextUniversalGroundedMixedRoundsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits limits(int fact){return ContextUniversalSignedFixedApplicationRoundsRunner.limits(fact);}
    static Result run(Snapshot x,List<Snapshot> a,Packet p,Map<Cut,PrivatePool> pools,Exchange e,int fact,int rounds){return ContextUniversalSignedUnitRounds.runGroundedMixed(x,a,p,pools,e,limits(fact),rounds,WORK);}
    static Result stable(Result r,Exchange e){ContextUniversalSignedFixedApplicationRoundsRunner.stable(r,e);for(Round n:r.history)for(ContextUniversalFrozenConstraints.Result c:n.checks.values())require(c.groundedMixed,"explicit mixed mode on every cut/round");return r;}
    static void incomplete(Result r,String phase,int completed){ContextUniversalSignedFixedApplicationRoundsRunner.incomplete(r,phase,completed,"atomic mixed refusal");++checks;}
    static Item item(Packet p,String pred){return p.items.stream().filter(i->i.atom.predicate.equals(pred)).findFirst().get();}
    static void refuted(Result r,int round){require(r.status==Status.REFUTED&&r.output==null&&r.symbolicOutput==null&&r.history.isEmpty()&&!r.refutations.isEmpty()&&r.completedRounds==round-1,r.reason);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Refutation f:r.refutations.values()){require(f.round==round&&!f.proofs.isEmpty(),"actual common-barrier refutation");for(Proof p:f.proofs){require(p.clause==null,"only empty rejection roots");ContextUniversalGroundedMixedApplicationsRunner.audit(p,seen);}}}
    static void baseline()throws Exception {
        Snapshot x=bind(true,"!@u p(u); !q(1);"),a=bind(false,"!@x p(x)&&q(x)->r(x);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> list=Collections.singletonList(a);
        incomplete(ContextUniversalSignedUnitRounds.runSymbolicHeads(x,list,p,Collections.emptyMap(),null,limits(1),8,WORK),"transfers",0);
        Result r=stable(run(x,list,p,Collections.emptyMap(),null,1,8),null);require(r.completedRounds==2&&r.history.get(0).commonChanged&&item(r.output.packet,"r").proofs.stream().allMatch(s->s.depth==1&&s.sources.size()==3),"mixed1 crosses all-cut barrier at fact1");require(stable(run(x,list,r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"exact final frames resume stable1");
        incomplete(run(x,list,p,Collections.emptyMap(),null,1,1),"round-limit",1);incomplete(run(x,list,p,Collections.emptyMap(),null,0,8),"transfers",0);
        Result old=ContextUniversalSignedUnitRounds.runSymbolicHeads(x,list,p,Collections.emptyMap(),null,limits(16),8,WORK);require(old.status==Status.STABLE_UNIT_POOLS&&item(old.output.packet,"r").proofs.stream().allMatch(s->s.depth==2)&&old.history.stream().flatMap(n->n.checks.values().stream()).noneMatch(c->c.groundedMixed),"old entry retains binary2 and explicit scope");Result improved=stable(run(x,list,old.output.packet,old.output.privatePools,old.symbolicOutput,16,8),old.symbolicOutput);require(improved.completedRounds==2&&improved.history.get(0).commonChanged&&improved.history.get(0).input.items.size()==improved.history.get(0).barrier.packet.items.size()&&item(improved.output.packet,"r").proofs.stream().allMatch(s->s.depth==1)&&item(old.output.packet,"r").proofs.stream().allMatch(s->s.depth==2),"same-Source grade-only fixed improvement forces another barrier without mutating input");
        Snapshot no=bind(false,"!~r(1);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,no),Arrays.asList(no,a))){Result collision=run(x,order,p,Collections.emptyMap(),null,1,8);refuted(collision,2);require(collision.refutations.get(Cut.of(no)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4),"peer collision next round empty2/four Sources in either order");}
        Snapshot directOpinion=bind(false,"!@u ~r(u);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,directOpinion),WORK);Result direct=run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,1,8);refuted(direct,1);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof v:direct.refutations.get(Cut.of(group)).proofs)ContextUniversalGroundedMixedApplicationsRunner.audit(v,seen);require(seen.stream().anyMatch(v->v.groundedMixedRecipe&&v.instantiatedDonors.size()==2),"direct empty retains actual mixed recipe/instances");Snapshot bad=bind(false,"!bad(1)||other(1);");incomplete(run(x,Arrays.asList(group,bad),p,Collections.emptyMap(),null,16,8),"checks",0);
        incomplete(run(x,list,ContextPrivateWitnessPoolRunner.common(x),Collections.emptyMap(),r.symbolicOutput,16,8),"preflight",0);incomplete(ContextUniversalSignedUnitRounds.runGroundedMixed(x,list,p,Collections.emptyMap(),null,limits(16),8,1),"preflight",0);
        Map<Cut,Packet> outputs=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())outputs.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(r.history.get(1).input,new ArrayList<>(outputs.keySet()),WORK).finish(outputs,WORK).status==FamilyStatus.INCOMPLETE,"stable mixed pools issue no family STEP/admission");
    }
    static void chainsAndAlternatives()throws Exception {
        Snapshot x=bind(true,"!@u p(u); !q(1);"),a=bind(false,"!@x p(x)&&q(x)->r(x);"),bridge=bind(false,"!s(1); !@x r(x)&&s(x)->t(x);"),opinion=bind(false,"!~t(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,bridge,opinion),Arrays.asList(opinion,bridge,a))){Result chain=run(x,order,p,Collections.emptyMap(),null,2,8);refuted(chain,3);require(chain.refutations.get(Cut.of(opinion)).proofs.stream().anyMatch(v->v.support.depth==3&&v.support.sources.size()==6),"mixed1 then fixed2 then peer empty3/six Sources across two barriers");}
        Snapshot symbolic=bind(false,"!@x p(x)&&q(x)->r(x); !@v r(1)&&q(1)->~s(v);"),yes=bind(false,"!s(987654);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(symbolic,yes),Arrays.asList(yes,symbolic))){Result no=run(x,order,p,Collections.emptyMap(),null,2,8);refuted(no,2);require(no.refutations.get(Cut.of(yes)).proofs.stream().anyMatch(v->v.support.depth==3&&v.support.sources.size()==5),"mixed-backed universal2 refutes previously unseen opinion next round, empty3/five Sources");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof v:no.refutations.get(Cut.of(yes)).proofs)ContextUniversalGroundedMixedApplicationsRunner.audit(v,seen);require(seen.stream().anyMatch(v->v.groundedMixedRecipe),"historical symbolic receipt flattens to actual mixed parents/instances");}
        Snapshot loop=bind(false,"!@x r(x)->r(x);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,loop),WORK);Result alts=stable(run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,2,8),null);Item r=item(alts.output.packet,"r");require(r.proofs.size()==2&&r.proofs.stream().anyMatch(s->s.depth==1&&s.sources.size()==3)&&r.proofs.stream().anyMatch(s->s.depth==2&&s.sources.size()==4),"full Source superset minimum retained after every barrier");incomplete(run(x,Collections.singletonList(group),p,Collections.emptyMap(),null,1,8),"transfers",0);
    }
    static void privateAndScope()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u,1); !@u p(u,1)&&q(u,1)->~r(u,1);"),a=bind(false,"!$u q(u,1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);Result r=stable(run(x,Collections.singletonList(a),p,pools,null,1,8),null);Item product=item(r.output.packet,"r");require(!product.atom.positive&&product.atom.arguments.get(0).origin.source.equals(a.primary.get(0).source)&&product.proofs.stream().allMatch(s->s.depth==1&&s.sources.size()==3&&s.sources.contains(a.primary.get(0).source)),"mixed negative1 retains actual private Origin/binding after common qualification");require(r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("q"))&&pool.common==p&&pool.local.items.stream().noneMatch(i->i.atom.predicate.equals("r")),"raw witness stays private and old frame immutable");require(stable(run(x,Collections.singletonList(a),r.output.packet,r.output.privatePools,r.symbolicOutput,1,1),r.symbolicOutput).completedRounds==1,"private continuation uses actual rebased pool");
        Snapshot yes=bind(false,"!@u r(u,1);");for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,yes),Arrays.asList(yes,a))){incomplete(run(x,order,p,pools,null,1,8),"symbolic-collection",0);Result no=run(x,order,p,pools,null,2,8);refuted(no,2);require(no.refutations.get(Cut.of(yes)).proofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==4&&v.support.sources.contains(a.primary.get(0).source)),"private mixed product requalifies independent universal, empty2/binding Source");}incomplete(run(x,Collections.singletonList(a),p,Collections.emptyMap(),null,1,8),"checks",0);
        Snapshot anchor=bind(true,"!anchor(1);"),positive=bind(false,"!@u p(u);"),negative=bind(false,"!~p(1);");Result independent=stable(run(anchor,Arrays.asList(positive,negative),ContextPrivateWitnessPoolRunner.common(anchor),Collections.emptyMap(),null,1,1),null);require(independent.output.packet.items.size()==1&&independent.symbolicOutput.units.isEmpty(),"unrelated anchor never communalizes sibling opinions");
        Snapshot own=bind(false,"!@u p(u,1); !$u q(u,1); !@u p(u,1)&&q(u,1)->~r(u,1);");Packet ap=ContextPrivateWitnessPoolRunner.common(anchor);PrivatePool raw=ContextWitnessResultTransport.privatePool(ap,anchor,own,WORK);Result local=stable(run(anchor,Collections.singletonList(own),ap,Collections.singletonMap(raw.cut,raw),null,1,8),null);require(local.completedRounds==2&&!local.history.get(0).commonChanged&&local.history.get(0).privateChanged&&local.output.packet.items.size()==1&&local.symbolicOutput.units.isEmpty()&&item(local.output.privatePools.get(raw.cut).local,"r").proofs.stream().allMatch(s->s.depth==1&&s.sources.stream().noneMatch(v->v.localX)),"foreign-only mixed growth stays private yet forces a second qualification");
        Snapshot sx=bind(true,"!anchor(1); !@u p(u); !@v q(v);"),rule=bind(false,"!@x p(x)&&q(x)->r(x);");Result symbolic=stable(run(sx,Collections.singletonList(rule),ContextPrivateWitnessPoolRunner.common(sx),Collections.emptyMap(),null,2,8),null);require(symbolic.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("r")&&u.support.depth==2&&!u.proof.groundedMixedRecipe),"all-symbolic donors retain binary2 scope within new scheduler");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("grounded-mixed-rounds-").toString());baseline();chainsAndAlternatives();privateAndScope();System.out.println("CONTEXT_UNIVERSAL_GROUNDED_MIXED_ROUNDS_PASS checks="+(checks+ContextUniversalSignedFixedApplicationRoundsRunner.checks+ContextUniversalGroundedMixedApplicationsRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
